// Extending Thread - locks you into single inheritance
class EmailThread extends Thread {
    private String recipient;

    public EmailThread(String recipient) {
        this.recipient = recipient;
    }

    @Override
    public void run() {
        System.out.println("Sending email to " + recipient);
    }
}

// Implementing Runnable - keeps inheritance open
class EmailTask implements Runnable {
    private String recipient;

    public EmailTask(String recipient) {
        this.recipient = recipient;
    }

    @Override
    public void run() {
        System.out.println("Sending email to " + recipient);
    }
}

// Usage with ExecutorService (modern approach)
var executor = Executors.newFixedThreadPool(5);
executor.execute(new EmailTask("user@example.com")); // Works perfectly
// executor.execute(new EmailThread("user@example.com")); // Won't compile!
