import java.util.concurrent.*;

// Runnable - no return value, catches exceptions internally
class NotificationTask implements Runnable {
    private String userId;

    public NotificationTask(String userId) {
        this.userId = userId;
    }

    @Override
    public void run() {
        try {
            // Send notification logic
            System.out.println("Notification sent to " + userId);
        } catch (Exception e) {
            // Must handle exceptions here
            System.err.println("Failed: " + e.getMessage());
        }
    }
}

// Callable - returns result, throws checked exceptions
class UserFetchTask implements Callable<String> {
    private Long userId;

    public UserFetchTask(Long userId) {
        this.userId = userId;
    }

    @Override
    public String call() throws Exception {  // Can throw checked exceptions
        // Simulate database fetch
        return "User-" + userId;  // Returns the result
    }
}

// Usage with ExecutorService
var executor = Executors.newFixedThreadPool(3);

executor.execute(new NotificationTask("user123"));  // Fire and forget

Future<String> future = executor.submit(new UserFetchTask(100L));
String userName = future.get();  // Blocks until result is ready
System.out.println("Fetched: " + userName);
