import java.util.concurrent.*;

public class RunnableLambdaDemo {

    public static void main(String[] args) {
        var executor = Executors.newFixedThreadPool(3);

        // Traditional anonymous class (verbose)
        executor.execute(new Runnable() {
            @Override
            public void run() {
                System.out.println("Anonymous class task");
            }
        });

        // Lambda expression - concise, same behavior
        executor.execute(() -> {
            System.out.println("Lambda task");
        });

        // Single statement lambda - even shorter
        executor.execute(() -> System.out.println("One-liner task"));

        // Method reference - maps existing method to Runnable
        executor.execute(RunnableLambdaDemo::logStatus);

        // Lambda with multiple statements
        executor.execute(() -> {
            String result = processData();
            System.out.println("Processed: " + result);
        });

        executor.shutdown();
    }

    static void logStatus() {  // No parameters, void return - matches Runnable
        System.out.println("Status check from method reference");
    }

    static String processData() {
        return "data-123";
    }
}
