import java.util.concurrent.*;

public class RunnableCompatibilityDemo {

    public static void main(String[] args) throws InterruptedException {
        // Define a Runnable task once
        Runnable notificationTask = () -> {
            System.out.println("Sending notification on " + 
                             Thread.currentThread().getName());
        };

        // Approach 1: Direct Thread (low-level, manual management)
        Thread thread = new Thread(notificationTask);
        thread.start();
        thread.join();  // Wait for completion

        // Approach 2: ExecutorService.execute (fire-and-forget)
        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.execute(notificationTask);  // Same Runnable, different execution

        // Approach 3: ExecutorService.submit (returns Future)
        Future<?> future = executor.submit(notificationTask);
        future.get();  // Block until completion
        System.out.println("Task completed: " + future.isDone());

        // Lambda directly inline
        executor.execute(() -> System.out.println("Inline task"));

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);
    }
}
