// Extending Thread for instrumentation - a valid but rare use case
class MonitoredThread extends Thread {
    private long startTime;
    private long endTime;
    private final Runnable task;

    public MonitoredThread(Runnable task, String name) {
        super(name);
        this.task = task;
    }

    @Override
    public void run() {
        startTime = System.currentTimeMillis();
        try {
            System.out.println(getName() + " started");
            task.run();  // Execute the actual task
        } catch (Exception e) {
            System.err.println(getName() + " failed: " + e);
        } finally {
            endTime = System.currentTimeMillis();
            System.out.println(getName() + " completed in " + 
                             (endTime - startTime) + "ms");
        }
    }

    public long getExecutionTime() {  // Custom method beyond standard Thread API
        return endTime - startTime;
    }
}

// Usage - but note you can't use this with ExecutorService
var thread = new MonitoredThread(() -> {
    // Some task logic
    System.out.println("Processing data...");
}, "Worker-1");
thread.start();
thread.join();
System.out.println("Execution time: " + thread.getExecutionTime() + "ms");
