import java.util.concurrent.*;

// ThreadLocal storing user context for request handling
public class UserContext {
    private static final ThreadLocal<String> currentUser = new ThreadLocal<>();

    public static void setUser(String userId) {
        currentUser.set(userId);  // Set for this thread only
    }

    public static String getUser() {
        return currentUser.get();  // Retrieve this thread's value
    }

    public static void clear() {
        currentUser.remove();  // Clean up to prevent leaks
    }
}

class RequestHandler implements Runnable {
    private final String userId;

    public RequestHandler(String userId) {
        this.userId = userId;
    }

    @Override
    public void run() {
        try {
            UserContext.setUser(userId);  // Set user for this thread
            processRequest();  // User context available everywhere
            auditLog();        // Still has access to user ID
        } finally {
            UserContext.clear();  // Critical: clean up ThreadLocal
        }
    }

    private void processRequest() {
        String user = UserContext.getUser();  // No parameter passing needed
        System.out.println("Processing request for " + user);
    }

    private void auditLog() {
        String user = UserContext.getUser();
        System.out.println("Audit log for " + user);
    }
}

// Multiple threads, each with isolated context
var executor = Executors.newFixedThreadPool(3);
executor.execute(new RequestHandler("user-1"));
executor.execute(new RequestHandler("user-2"));  // Won't see user-1's context
